CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans( dim int, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit int ) RETURNS TABLE(moved bigint, sample jsonb) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_chashes bytea[]; v_moved bigint; v_sample jsonb; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_quarantine_orphans: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
IF dim = 384 THEN SELECT array_agg(c.chash) INTO v_chashes FROM nexus.chunks_384 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash );
IF v_chashes IS NULL THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb; RETURN; END IF;
INSERT INTO nexus.chunks_384 (tenant_id, collection, chash, chunk_text, embedding, metadata) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) FROM nexus.chunks_384 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = ANY(v_chashes) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, metadata = EXCLUDED.metadata;
WITH del AS ( DELETE FROM nexus.chunks_384 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = ANY(v_chashes) RETURNING c.chash, c.metadata->>'title' AS title ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(chash, 'hex'), 'title', title)) AS s FROM (SELECT chash, title FROM del LIMIT p_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
RETURN QUERY SELECT v_moved, v_sample; RETURN;
ELSIF dim = 768 THEN SELECT array_agg(c.chash) INTO v_chashes FROM nexus.chunks_768 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash );
IF v_chashes IS NULL THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb; RETURN; END IF;
INSERT INTO nexus.chunks_768 (tenant_id, collection, chash, chunk_text, embedding, metadata) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) FROM nexus.chunks_768 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = ANY(v_chashes) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, metadata = EXCLUDED.metadata;
WITH del AS ( DELETE FROM nexus.chunks_768 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = ANY(v_chashes) RETURNING c.chash, c.metadata->>'title' AS title ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(chash, 'hex'), 'title', title)) AS s FROM (SELECT chash, title FROM del LIMIT p_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
RETURN QUERY SELECT v_moved, v_sample; RETURN;
ELSIF dim = 1024 THEN SELECT array_agg(c.chash) INTO v_chashes FROM nexus.chunks_1024 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash );
IF v_chashes IS NULL THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb; RETURN; END IF;
INSERT INTO nexus.chunks_1024 (tenant_id, collection, chash, chunk_text, embedding, metadata) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) FROM nexus.chunks_1024 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = ANY(v_chashes) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, metadata = EXCLUDED.metadata;
WITH del AS ( DELETE FROM nexus.chunks_1024 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = ANY(v_chashes) RETURNING c.chash, c.metadata->>'title' AS title ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(chash, 'hex'), 'title', title)) AS s FROM (SELECT chash, title FROM del LIMIT p_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
RETURN QUERY SELECT v_moved, v_sample; RETURN; END IF; END; $$

CREATE OR REPLACE FUNCTION nexus.gc_restore_rereferenced( dim int, p_tenant_id text, p_quarantine_collection text, p_origin_collection text ) RETURNS bigint LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_chashes bytea[]; v_restored bigint := 0; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_restore_rereferenced: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
IF dim = 384 THEN SELECT array_agg(c.chash) INTO v_chashes FROM nexus.chunks_384 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash );
IF v_chashes IS NULL THEN RETURN 0; END IF;
INSERT INTO nexus.chunks_384 (tenant_id, collection, chash, chunk_text, embedding, metadata) SELECT p_tenant_id, p_origin_collection, c.chash, c.chunk_text, c.embedding, (COALESCE(c.metadata, '{}'::jsonb) - 'quarantined_at' - 'origin_collection') FROM nexus.chunks_384 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, metadata = EXCLUDED.metadata;
DELETE FROM nexus.chunks_384 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes);
v_restored := array_length(v_chashes, 1); RETURN v_restored;
ELSIF dim = 768 THEN SELECT array_agg(c.chash) INTO v_chashes FROM nexus.chunks_768 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash );
IF v_chashes IS NULL THEN RETURN 0; END IF;
INSERT INTO nexus.chunks_768 (tenant_id, collection, chash, chunk_text, embedding, metadata) SELECT p_tenant_id, p_origin_collection, c.chash, c.chunk_text, c.embedding, (COALESCE(c.metadata, '{}'::jsonb) - 'quarantined_at' - 'origin_collection') FROM nexus.chunks_768 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, metadata = EXCLUDED.metadata;
DELETE FROM nexus.chunks_768 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes);
v_restored := array_length(v_chashes, 1); RETURN v_restored;
ELSIF dim = 1024 THEN SELECT array_agg(c.chash) INTO v_chashes FROM nexus.chunks_1024 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash );
IF v_chashes IS NULL THEN RETURN 0; END IF;
INSERT INTO nexus.chunks_1024 (tenant_id, collection, chash, chunk_text, embedding, metadata) SELECT p_tenant_id, p_origin_collection, c.chash, c.chunk_text, c.embedding, (COALESCE(c.metadata, '{}'::jsonb) - 'quarantined_at' - 'origin_collection') FROM nexus.chunks_1024 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes) ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding = EXCLUDED.embedding, metadata = EXCLUDED.metadata;
DELETE FROM nexus.chunks_1024 c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes);
v_restored := array_length(v_chashes, 1); RETURN v_restored; END IF; END; $$

CREATE OR REPLACE FUNCTION nexus.gc_expire_quarantine(
    dim                      int,
    p_tenant_id              text,
    p_quarantine_collection  text,
    p_origin_collection      text,
    p_cutoff                 text,
    p_floor_fraction         float8,
    p_floor_min_chunks       int,
    p_force                  boolean
)
RETURNS TABLE(expired bigint, refused bigint)
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_mine     bigint;
    v_chashes  bytea[];
    v_expired  bigint;
    v_frac     float8;
BEGIN
    IF dim NOT IN (384, 768, 1024) THEN
        RAISE EXCEPTION
            'gc_expire_quarantine: unsupported dim %. Supported values: 384, 768, 1024',
            dim;
    END IF;

    IF dim = 384 THEN
        SELECT count(*),
               array_agg(chash) FILTER (
                   WHERE COALESCE(metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff)
          INTO v_mine, v_chashes
          FROM nexus.chunks_384
         WHERE tenant_id  = p_tenant_id
           AND collection = p_quarantine_collection
           AND COALESCE(metadata->>'origin_collection', p_origin_collection) = p_origin_collection;

        v_expired := COALESCE(array_length(v_chashes, 1), 0);
        IF v_expired = 0 THEN
            RETURN QUERY SELECT 0::bigint, 0::bigint;
            RETURN;
        END IF;

        v_frac := v_expired::float8 / v_mine::float8;
        IF v_expired >= p_floor_min_chunks AND v_frac > p_floor_fraction AND NOT p_force THEN
            RETURN QUERY SELECT 0::bigint, v_expired;
            RETURN;
        END IF;

        DELETE FROM nexus.chunks_384
         WHERE tenant_id = p_tenant_id AND collection = p_quarantine_collection
           AND chash = ANY(v_chashes);

        RETURN QUERY SELECT v_expired, 0::bigint;
        RETURN;

    ELSIF dim = 768 THEN
        SELECT count(*),
               array_agg(chash) FILTER (
                   WHERE COALESCE(metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff)
          INTO v_mine, v_chashes
          FROM nexus.chunks_768
         WHERE tenant_id  = p_tenant_id
           AND collection = p_quarantine_collection
           AND COALESCE(metadata->>'origin_collection', p_origin_collection) = p_origin_collection;

        v_expired := COALESCE(array_length(v_chashes, 1), 0);
        IF v_expired = 0 THEN
            RETURN QUERY SELECT 0::bigint, 0::bigint;
            RETURN;
        END IF;

        v_frac := v_expired::float8 / v_mine::float8;
        IF v_expired >= p_floor_min_chunks AND v_frac > p_floor_fraction AND NOT p_force THEN
            RETURN QUERY SELECT 0::bigint, v_expired;
            RETURN;
        END IF;

        DELETE FROM nexus.chunks_768
         WHERE tenant_id = p_tenant_id AND collection = p_quarantine_collection
           AND chash = ANY(v_chashes);

        RETURN QUERY SELECT v_expired, 0::bigint;
        RETURN;

    ELSIF dim = 1024 THEN
        SELECT count(*),
               array_agg(chash) FILTER (
                   WHERE COALESCE(metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff)
          INTO v_mine, v_chashes
          FROM nexus.chunks_1024
         WHERE tenant_id  = p_tenant_id
           AND collection = p_quarantine_collection
           AND COALESCE(metadata->>'origin_collection', p_origin_collection) = p_origin_collection;

        v_expired := COALESCE(array_length(v_chashes, 1), 0);
        IF v_expired = 0 THEN
            RETURN QUERY SELECT 0::bigint, 0::bigint;
            RETURN;
        END IF;

        v_frac := v_expired::float8 / v_mine::float8;
        IF v_expired >= p_floor_min_chunks AND v_frac > p_floor_fraction AND NOT p_force THEN
            RETURN QUERY SELECT 0::bigint, v_expired;
            RETURN;
        END IF;

        DELETE FROM nexus.chunks_1024
         WHERE tenant_id = p_tenant_id AND collection = p_quarantine_collection
           AND chash = ANY(v_chashes);

        RETURN QUERY SELECT v_expired, 0::bigint;
        RETURN;
    END IF;
END;
$$

GRANT EXECUTE ON FUNCTION nexus.gc_quarantine_orphans(int, text, text, text, text, int) TO nexus_svc;
GRANT EXECUTE ON FUNCTION nexus.gc_restore_rereferenced(int, text, text, text) TO nexus_svc;
GRANT EXECUTE ON FUNCTION nexus.gc_expire_quarantine(int, text, text, text, text, float8, int, boolean) TO nexus_svc;

rollback.sql:
DO $$
BEGIN
    IF to_regprocedure('nexus.gc_expire_quarantine(int, text, text, text, text, float8, int, boolean)') IS NOT NULL THEN
        REVOKE EXECUTE ON FUNCTION nexus.gc_expire_quarantine(int, text, text, text, text, float8, int, boolean) FROM nexus_svc;
    END IF;
    IF to_regprocedure('nexus.gc_restore_rereferenced(int, text, text, text)') IS NOT NULL THEN
        REVOKE EXECUTE ON FUNCTION nexus.gc_restore_rereferenced(int, text, text, text) FROM nexus_svc;
    END IF;
    IF to_regprocedure('nexus.gc_quarantine_orphans(int, text, text, text, text, int)') IS NOT NULL THEN
        REVOKE EXECUTE ON FUNCTION nexus.gc_quarantine_orphans(int, text, text, text, text, int) FROM nexus_svc;
    END IF;
END
$$;
